export function classWorkspaceType(value='demo'){
  const type=CLASS_TYPES.includes(clean(value,30))?clean(value,30):'demo';
  return ['demo','webinar','trial'].includes(type)?'demo':type;
}

function classType(value='online_class'){
  const type=clean(value,30);return CLASS_TYPES.includes(type)?type:'online_class';
}
function classDays(value){return unique((Array.isArray(value)?value:jsonParse(value,[])).map(x=>clean(x,3).toLowerCase()).filter(x=>DAYS.includes(x)),7);}
function nextClassDate(startDate,daysValue){const start=validDate(startDate),allowed=new Set(classDays(daysValue));if(!start||!allowed.size)return start;for(let offset=0;offset<14;offset++){const value=new Date(`${start}T12:00:00Z`);value.setUTCDate(value.getUTCDate()+offset);const date=value.toISOString().slice(0,10);if(allowed.has(DAYS[value.getUTCDay()]))return date;}return start;}
function coachAvailability(value){const parsed=classDays(value);return parsed.length?parsed:[...DAYS];}
function coachClassTypes(value){const raw=Array.isArray(value)?value:jsonParse(value,[]),parsed=unique(raw.map(x=>clean(x,30)).filter(x=>CLASS_TYPES.includes(x)),CLASS_TYPES.length);return parsed.length?parsed:[...CLASS_TYPES];}
