export async function removeClassMember(env,{memberId,eventType='',confirmation=''}={}){
  await ensureDanceStudioSchema(env);const id=Math.floor(Number(memberId||0)),workspace=classWorkspaceType(eventType);
  if(!Number.isFinite(id)||id<1)throw new Error('Choose a valid member before removing class access.');
  if(clean(confirmation,20).toUpperCase()!=='REMOVE')throw new Error('Type REMOVE to confirm that this member should move to Past Members.');
  const member=await env.DB.prepare('SELECT * FROM webinar_members WHERE id=? LIMIT 1').bind(id).first();
  if(!member)throw new Error('Member membership was not found. Refresh the class workspace and try again.');
  if(classWorkspaceType(member.event_type)!==workspace)throw new Error('This member does not belong to the selected class workspace.');
  if(clean(member.status,20)==='past')return {ok:true,memberId:id,alreadyPast:true};
  const reason='Removed from this class by an administrator.';
  await env.DB.prepare("UPDATE webinar_members SET status='past',payment_status='removed_by_admin',membership_reason=?,moved_to_past_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(reason,id).run();
  await env.DB.prepare("UPDATE webinar_member_reminders SET status='cancelled',error_text='Member was removed from the class by an administrator.' WHERE member_id=? AND status='pending'").bind(id).run().catch(()=>{});
  const eventKey=`${id}:past:admin-removed:${Date.now()}`;
  await env.DB.prepare(`INSERT OR IGNORE INTO class_member_status_events(event_key,member_id,event_type,old_status,new_status,reason,order_reference) VALUES(?,?,?,?,?,?,?)`).bind(eventKey,id,workspace,clean(member.status,20)||'current','past',reason,clean(member.order_reference,120)).run();
  return {ok:true,memberId:id,status:'past'};
}

export async function acknowledgePastMemberNotifications(env,eventType){await ensureDanceStudioSchema(env);const workspace=classWorkspaceType(eventType);await env.DB.prepare("UPDATE class_member_status_events SET read_at=CURRENT_TIMESTAMP WHERE event_type=? AND new_status='past' AND trim(read_at)='' ").bind(workspace).run();return {ok:true};}
